{
  "qid": "0021-L2-01",
  "sample_id": "0021",
  "gen_prompt": "写实商业摄影：一辆讴歌轿车独自停放，车头正对镜头；采用近距离正面构图，让完整车头占据画面主体。",
  "invocation": "L2",
  "knowledge_dim": "汽车品牌视觉识别与车标几何结构",
  "fidelity_checks": [
    {
      "check": "车头上呈现可用于识别讴歌汽车品牌的图形徽标，而非以对“讴歌”一词的歌唱、颂扬等字面演绎代替品牌识别。",
      "anchor": {
        "type": "combination",
        "constraint_refs": [
          "1",
          "11"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "0 Fail：车头完全没有可识别的讴歌图形徽标，或用歌唱、颂扬人物等中文字面场景代替汽车品牌徽标。",
        "tier_1": "1 Pass：车头明确出现可识别为讴歌的图形徽标，没有以中文字面场景替代品牌识别。",
        "tier_2": "2 Excel：在满足 Pass 的基础上，徽标位置、比例和完整度均高度可信，即使不依赖文字也能迅速、无歧义地识别品牌。"
      },
      "variants_used": "无",
      "visibility_requirement": "最低可见条件为车头品牌标识区域在近距离正面构图中清楚露出；若因裁切、遮挡、过小或模糊而无法确认图形徽标，记 0。"
    },
    {
      "check": "讴歌徽标具有包围中央符号的椭圆形或近椭圆形外环。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "2"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "0 Fail：没有外环，外框明显不是椭圆或近椭圆，或外框未包围中央符号。",
        "tier_1": "1 Pass：可见完整的椭圆形或近椭圆形环框，中央符号明确位于其包围范围内。",
        "tier_2": "2 Excel：在满足 Pass 的基础上，环框轮廓连续、对称且比例准确，与中央符号之间的留白均衡清楚。"
      },
      "variants_used": "无",
      "visibility_requirement": "外环及其与中央符号的包围关系必须可见；若外环因裁切、反光或遮挡而无法判读，记 0。"
    },
    {
      "check": "外环内的中央主体呈可辨认的大写字母“A”轮廓，同时具有抽象制图卡钳式的几何造型。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "3"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "0 Fail：中央主体缺失，不能辨认为“A”形轮廓，或完全不具备卡钳式抽象几何特征。",
        "tier_1": "1 Pass：中央主体同时清楚呈现“A”形整体轮廓和抽象卡钳式几何结构。",
        "tier_2": "2 Excel：在满足 Pass 的基础上，卡钳意象与“A”形轮廓融合精确，结构比例和左右对称性高度可信。"
      },
      "variants_used": "无",
      "visibility_requirement": "中央主体必须达到可辨认其整体轮廓和几何设计的尺寸；无法看清时记 0。"
    },
    {
      "check": "中央卡钳形主体具有两条从下方向上延伸并向中央收拢的斜向构件，由此形成“A”形外轮廓。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "4"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "0 Fail：缺少任一侧斜向构件，两侧构件不向上收拢，或无法形成可辨认的“A”形轮廓。",
        "tier_1": "1 Pass：左右两条斜向构件均从下方向上延伸并朝中央收拢，整体形成明确的“A”形。",
        "tier_2": "2 Excel：在满足 Pass 的基础上，两侧斜构件角度、间距和收拢关系精确对称，轮廓清晰且富有机械制图感。"
      },
      "variants_used": "无",
      "visibility_requirement": "两侧斜构件须同时可见；若一侧被裁切、遮挡或糊失而不能确认结构，记 0。"
    },
    {
      "check": "中央“A”形两侧构件之间具有明确的横向连接构件，形成类似字母“A”横杠的结构。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "5"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "0 Fail：两侧构件之间完全没有横向连接，或所谓连接结构位置和方向明显不能构成“A”的横杠。",
        "tier_1": "1 Pass：两侧构件之间存在清楚可见的横向连接构件，并准确发挥“A”形横杠的结构作用。",
        "tier_2": "2 Excel：在满足 Pass 的基础上，横向构件与两侧斜构件衔接精确、粗细协调，微小尺寸下仍清晰可辨。"
      },
      "variants_used": "无",
      "visibility_requirement": "徽标尺寸必须足以看清横向连接构件；若该区域被高光吞没、模糊或遮挡，记 0。"
    },
    {
      "check": "中央“A”形不是整块实心封闭三角形，其内部保留清楚可见的镂空或负形区域。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "6"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "0 Fail：中央图形被画成整块实心封闭三角形，或内部完全没有可见的镂空、开口或负形。",
        "tier_1": "1 Pass：中央结构不是实心三角形，内部具有明确可见且与构件边界分离的负形区域。",
        "tier_2": "2 Excel：在满足 Pass 的基础上，内部负形边界锐利、比例准确，并与横杠及两侧构件共同形成层次清楚的结构。"
      },
      "variants_used": "无",
      "visibility_requirement": "中央内部区域必须可见；若受分辨率、阴影或反光影响而无法判断是否镂空，记 0。"
    },
    {
      "check": "讴歌徽标的中央主体不是缺少卡钳化几何结构的普通印刷体大写字母“A”。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "7"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "0 Fail：中央主体只是常规字体字形或字体贴字，缺少讴歌特有的卡钳化几何构造。",
        "tier_1": "1 Pass：中央主体明显经过卡钳式几何抽象，不能被误认为普通印刷体“A”。",
        "tier_2": "2 Excel：在满足 Pass 的基础上，机械卡钳式端部、构件组织和制图感均表达精确，与普通字体的区别一目了然。"
      },
      "variants_used": "无",
      "visibility_requirement": "中央主体细节须足以区分定制几何符号与普通字体；无法区分时记 0。"
    },
    {
      "check": "车头核心品牌位置没有以本田“H”或雷克萨斯、英菲尼迪等其他汽车品牌图形替代或冒充讴歌徽标。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "8"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "0 Fail：核心位置出现其他汽车品牌标志并被当作主体，或讴歌结构与其他品牌标志混淆到无法正确识别。",
        "tier_1": "1 Pass：核心位置使用正确的讴歌图形，没有被其他汽车品牌标志替代或冒充。",
        "tier_2": "2 Excel：在满足 Pass 的基础上，品牌图形特征高度明确，无混合标、错标或近似其他品牌的歧义。"
      },
      "variants_used": "无",
      "visibility_requirement": "核心品牌位置必须清晰可判；若图形过小或模糊到无法排除其他品牌标志，记 0。"
    },
    {
      "check": "品牌识别不只依赖“讴歌”或“ACURA”文字，画面中同时具有独立成立的卡钳形“A”图形徽标。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "9"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "0 Fail：只出现“讴歌”或“ACURA”等文字而完全缺少正确图形徽标，或文字成为唯一可用的品牌证据。",
        "tier_1": "1 Pass：无论是否附带文字，正确的卡钳形“A”图形徽标均清楚存在并可独立识别。",
        "tier_2": "2 Excel：在满足 Pass 的基础上，图形徽标拥有明确的视觉主次和完整结构，附带文字若存在也不会干扰图形识别。"
      },
      "variants_used": "无",
      "visibility_requirement": "必须能独立观察图形徽标；仅能读到文字而图形不可见或不可判时记 0。"
    },
    {
      "check": "讴歌徽标核心保持抽象几何式卡钳形“A”结构，没有被画成或并入狮子、鹰、奔马、人物等具象形象。",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "10"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "0 Fail：核心图形被替换为具象动物、人物或其他形象，或这些形象与核心结构融合到破坏卡钳形“A”的识别。",
        "tier_1": "1 Pass：核心图形保持纯粹、可辨的抽象几何式卡钳形“A”，未被具象形象替代或并入。",
        "tier_2": "2 Excel：在满足 Pass 的基础上，抽象几何语言高度统一、简洁精确，核心结构不存在任何具象化歧义。"
      },
      "variants_used": "无",
      "visibility_requirement": "核心图形整体必须清楚可见；若因遮挡或模糊而无法判断是否混入具象形象，记 0。"
    }
  ],
  "alignment_checks": [
    {
      "check": "画面中恰好出现一辆轿车。",
      "facet": "quantity",
      "rubric": {
        "tier_0": "0 Fail：没有轿车，或出现两辆及以上轿车。",
        "tier_1": "1 Pass：画面中清楚且恰好出现一辆轿车。",
        "tier_2": "2 Excel：在满足 Pass 的基础上，唯一车辆边界完整明确，不存在倒影、海报或背景车辆造成的数量歧义。"
      }
    },
    {
      "check": "轿车处于停放状态且车头正对镜头。",
      "facet": "fullbody_action",
      "rubric": {
        "tier_0": "0 Fail：车辆明显处于行驶动作，或以侧面、车尾为主要朝向。",
        "tier_1": "1 Pass：车辆明确静止停放，车头基本正对镜头。",
        "tier_2": "2 Excel：在满足 Pass 的基础上，车身中轴与镜头方向高度一致，静止状态和正面朝向表达无歧义。"
      }
    },
    {
      "check": "完整车头以近距离正面构图占据画面主体。",
      "facet": "subject_prominence",
      "rubric": {
        "tier_0": "0 Fail：车头缺失、被严重裁切、占比过小，或被无关背景喧宾夺主。",
        "tier_1": "1 Pass：完整车头处于近距离视野内，并明确占据画面主导地位。",
        "tier_2": "2 Excel：在满足 Pass 的基础上，车头完整收纳、主体占比充分且视觉焦点高度集中，没有干扰元素争夺注意力。"
      }
    },
    {
      "check": "整幅图采用写实商业摄影风格。",
      "facet": "style_control",
      "rubric": {
        "tier_0": "0 Fail：画面属于明显不同的风格体系，如卡通、手绘、油画或低多边形渲染。",
        "tier_1": "1 Pass：全画一致呈现可信的写实商业汽车摄影语言。",
        "tier_2": "2 Excel：在满足 Pass 的基础上，镜头质感、产品呈现和摄影细节均达到高规格汽车广告级效果，且风格全局统一。"
      }
    }
  ],
  "leak_check": {
    "对照表": [
      {
        "constraint_ref": "1",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "2",
